package com.guocheng.mediapocket;
import android.app.Activity;
import android.view.Gravity;
import android.view.View;
import android.widget.FrameLayout;
import android.widget.TextView;
import android.widget.Toast;
import java.util.ArrayList;
import java.util.Map;
import java.util.WeakHashMap;
/**
 * 第二字幕。VLC 3.0.22 和内置 Media3 都只有一条文本渲染器，两条内嵌轨不能同时解。
 * 第二条如果是外挂 SRT / ASS / VTT，就自己按时间画在画面上，可以和播放器正在显示的第一字幕叠在一起。
 */
final class SecondarySubtitle {
 private SecondarySubtitle(){}
 static final class State {volatile String url="";volatile SubtitleCueClock.Cue[] cues=new SubtitleCueClock.Cue[0];}
 static final Map<Activity,State> ALL=new WeakHashMap<>();
 static State state(Activity a){State s=ALL.get(a);if(s==null){s=new State();ALL.put(a,s);}return s;}
 static String key(Activity a){return "subtitle2Url:"+SubtitleMemory.id(a);}
 static void clear(Activity a){String id=SubtitleMemory.id(a);if(!id.isEmpty())a.getSharedPreferences("data",0).edit().remove("subtitle2Url:"+id).remove("subtitle2Name:"+id).remove("subtitle2Referer:"+id).remove("subtitle2Ua:"+id).apply();State s=state(a);s.url="";s.cues=new SubtitleCueClock.Cue[0];TextView tv=find(a);if(tv!=null){tv.setText("");tv.setVisibility(View.GONE);}}
 static java.util.Map<String,String> storedHeaders(Activity a,String id){java.util.LinkedHashMap<String,String> headers=new java.util.LinkedHashMap<>();if(a==null||id==null||id.isEmpty())return headers;String referer=a.getSharedPreferences("data",0).getString("subtitle2Referer:"+id,"");String agent=a.getSharedPreferences("data",0).getString("subtitle2Ua:"+id,"");if(referer!=null&&!referer.isEmpty())headers.put("Referer",referer);if(agent!=null&&!agent.isEmpty())headers.put("User-Agent",agent);return headers;}
 static void restore(Activity a){if(a==null||a.isFinishing())return;String id=SubtitleMemory.id(a);if(id.isEmpty())return;String url=a.getSharedPreferences("data",0).getString("subtitle2Url:"+id,"");State s=state(a);if(url==null||url.isEmpty()||!SubtitleAuto.secondaryUrl(url)){s.url="";s.cues=new SubtitleCueClock.Cue[0];if(url!=null&&!url.isEmpty())a.getSharedPreferences("data",0).edit().remove("subtitle2Url:"+id).remove("subtitle2Name:"+id).remove("subtitle2Referer:"+id).remove("subtitle2Ua:"+id).apply();return;}if(url.equals(s.url)&&s.cues.length>0)return;load(a,url,a.getSharedPreferences("data",0).getString("subtitle2Name:"+id,"第二字幕"),storedHeaders(a,id),false,false);}
 static void load(Activity a,org.json.JSONObject item,boolean toast){if(item==null)return;load(a,item.optString("url"),item.optString("lang",item.optString("name","外挂字幕")),SubtitleAuto.sidecarHeaders(item),toast,false);}
 static void load(Activity a,String url,String name,java.util.Map<String,String> headers,boolean toast,boolean userChosenLocal){if(a==null||url==null||url.isEmpty())return;boolean remote=SubtitleAuto.secondaryUrl(url),local=userChosenLocal&&SubtitleAuto.secondaryLocal(url);if(!remote&&!local){if(toast)Toast.makeText(a,"第二字幕只接受网络字幕，或你自己选的本地字幕",Toast.LENGTH_LONG).show();return;}String id=SubtitleMemory.id(a);State s=state(a);s.url=url;java.util.Map<String,String> keep=SubtitleAuto.safeSecondaryHeaders(headers);if(!id.isEmpty())a.getSharedPreferences("data",0).edit().putString("subtitle2Url:"+id,url).putString("subtitle2Name:"+id,name==null?"":name).putString("subtitle2Referer:"+id,keep.get("Referer")==null?"":keep.get("Referer")).putString("subtitle2Ua:"+id,keep.get("User-Agent")==null?"":keep.get("User-Agent")).apply();final String label=name==null||name.isEmpty()?"第二字幕":name;final java.util.Map<String,String> extra=headers==null?java.util.Collections.emptyMap():headers;OnlineSubtitleSearch.IO.execute(()->{try{byte[] bytes=local?ExternalSubtitleStore.read(url):SubtitleHttp.download(url,extra);if(bytes==null||bytes.length==0)throw new Exception("字幕是空的");String text=SubtitleTextRules.timeline(SubtitleTextRules.decode(OnlineSubtitleRules.unwrap(bytes)));java.lang.reflect.Method parse=Class.forName("com.guocheng.mediapocket.SubtitleParser").getDeclaredMethod("parse",String.class);parse.setAccessible(true);Object parsed=parse.invoke(null,text);if(!(parsed instanceof ArrayList)||((ArrayList<?>)parsed).isEmpty())throw new Exception("这不是可显示的 SRT、ASS 或 VTT");ArrayList<?> list=(ArrayList<?>)parsed;int n=Math.min(20000,list.size());SubtitleCueClock.Cue[] cues=new SubtitleCueClock.Cue[n];for(int i=0;i<n;i++){Object cue=list.get(i);Object start=OnlineSubtitleSearch.field(cue,"start"),end=OnlineSubtitleSearch.field(cue,"end"),body=OnlineSubtitleSearch.field(cue,"text");cues[i]=new SubtitleCueClock.Cue(start instanceof Integer?(Integer)start:0,end instanceof Integer?(Integer)end:0,body==null?"":body.toString());}a.runOnUiThread(()->{if(a.isFinishing()||!url.equals(s.url))return;s.cues=cues;tick(a);if(toast)Toast.makeText(a,"第二字幕已叠上 · "+label,Toast.LENGTH_SHORT).show();});}catch(Exception e){a.runOnUiThread(()->{if(a.isFinishing())return;s.cues=new SubtitleCueClock.Cue[0];if(toast)Toast.makeText(a,"第二字幕没有叠上："+(e.getMessage()==null?"读不了这个文件":e.getMessage()),Toast.LENGTH_LONG).show();});}});}
 static TextView find(Activity a){Object root=OnlineSubtitleSearch.field(a,"root");if(!(root instanceof FrameLayout))return null;return ((FrameLayout)root).findViewWithTag("mp-sub-2");}
 static TextView ensure(Activity a){TextView have=find(a);if(have!=null)return have;Object root=OnlineSubtitleSearch.field(a,"root");if(!(root instanceof FrameLayout))return null;TextView tv=new TextView(a);tv.setTag("mp-sub-2");tv.setGravity(Gravity.CENTER);tv.setClickable(false);tv.setFocusable(false);float d=a.getResources().getDisplayMetrics().density;tv.setPadding(Math.round(20*d),0,Math.round(20*d),0);FrameLayout.LayoutParams lp=new FrameLayout.LayoutParams(-1,-2,Gravity.BOTTOM);((FrameLayout)root).addView(tv,lp);return tv;}
 static void tick(Activity a){try{if(a==null||a.isFinishing())return;State s=ALL.get(a);if(s==null||s.cues==null||s.cues.length==0){TextView gone=find(a);if(gone!=null&&gone.getVisibility()!=View.GONE){gone.setText("");gone.setVisibility(View.GONE);}return;}TextView tv=ensure(a);if(tv==null)return;int pos;if(a instanceof SystemPlayerActivity){Media3VideoView video=((SystemPlayerActivity)a).video;pos=video==null?-1:video.getCurrentPosition();}else pos=EmbyPlayback.position(a);String text=SubtitleCueClock.textAt(s.cues,pos,a.getSharedPreferences("data",0).getInt("sub.offsetMs",0));if(!text.equals(String.valueOf(tv.getText())))tv.setText(text);tv.setVisibility(text.isEmpty()?View.GONE:View.VISIBLE);boolean controls;if(a instanceof SystemPlayerActivity){SystemPlayerActivity sys=(SystemPlayerActivity)a;controls=sys.bottom!=null&&sys.bottom.getVisibility()==View.VISIBLE;}else{Object top=OnlineSubtitleSearch.field(a,"top");controls=top instanceof View&&((View)top).getVisibility()==View.VISIBLE;}int base=Math.round((controls?168:48)*a.getResources().getDisplayMetrics().density);SubtitleStyle.style(a,tv,false,base,SubtitleStyle.hdr(TrackSelection.stream(a)),true);tv.bringToFront();}catch(Exception ignored){}}
}
